# Implement m1: Add .skip, .invalidate, .invalidate_all to memoize wrapper
# Read current file
with open('funcy/calc.py') as f:
    content = f.read()

# Find the memoize decorator function and modify it
# We need to add invalidate and invalidate_all methods to the wrapper

old_code = '''    def decorator(func):
        memory = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            # NOTE: we inline this here but not in @cache,
            #       since @memoize also targets microoptimizations.
            key = key_func(*args, **kwargs) if key_func else \\
                  args + tuple(sorted(kwargs.items())) if kwargs else args
            try:
                return memory[key]
            except KeyError:
                try:
                    value = memory[key] = func(*args, **kwargs)
                    return value
                except SkipMemoization as e:
                    return e.args[0] if e.args else None

        wrapper.memory = memory
        return wrapper'''

new_code = '''    def decorator(func):
        memory = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            # NOTE: we inline this here but not in @cache,
            #       since @memoize also targets microoptimizations.
            key = key_func(*args, **kwargs) if key_func else \\
                  args + tuple(sorted(kwargs.items())) if kwargs else args
            try:
                return memory[key]
            except KeyError:
                try:
                    value = memory[key] = func(*args, **kwargs)
                    return value
                except SkipMemoization as e:
                    return e.args[0] if e.args else None

        wrapper.memory = memory

        def invalidate(*args, **kwargs):
            key = key_func(*args, **kwargs) if key_func else \\
                  args + tuple(sorted(kwargs.items())) if kwargs else args
            memory.pop(key, None)
        wrapper.invalidate = invalidate

        def invalidate_all():
            memory.clear()
        wrapper.invalidate_all = invalidate_all

        return wrapper'''

if old_code in content:
    content = content.replace(old_code, new_code)
    with open('funcy/calc.py', 'w') as f:
        f.write(content)
    print("m1: Successfully updated calc.py")
